at::Tensor& ZeroInplaceKernelGcu(at::Tensor& self) {
  if (self.numel() == 0) {
    return self;
  }
  if (!gcu::TopsatenSupportsDtype(self.scalar_type()) ||
      !self.is_contiguous()) {
    auto host = self.cpu();
    host.zero_();
    self.copy_(host);
    return self;
  }
  gcu::TopsatenTensorWrapper t_self(self);
  EXEC_TOPSATEN_CMD(topsatenZero, self, t_self.get());
  return self;
}

